function kthLargest(nums, k):
  minHeap = new MinHeap()  // stores k largest
  for x in nums:
    if minHeap.size < k:
      minHeap.push(x)
    else if x > minHeap.peek():
      minHeap.pop()
      minHeap.push(x)
  return minHeap.peek()  // kth largest

